public class RetrierTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        int[] calls = { 0 };
        Flaky succeedsThird = () -> {
            calls[0]++;
            if (calls[0] < 3) {
                throw new IllegalStateException("boom " + calls[0]);
            }
            return "ok";
        };
        try {
            check("succeeds on the 3rd attempt", "ok", Retrier.retry(succeedsThird, 5));
        } catch (Exception e) {
            check("succeeds on the 3rd attempt", "ok", "threw " + e.getClass().getSimpleName());
        }
        check("exactly 3 calls were made", 3, calls[0]);

        int[] failCalls = { 0 };
        Flaky alwaysFails = () -> {
            failCalls[0]++;
            throw new IllegalStateException("boom " + failCalls[0]);
        };
        String outcome;
        try {
            outcome = "returned " + Retrier.retry(alwaysFails, 2);
        } catch (RuntimeException e) {
            Throwable cause = e.getCause();
            outcome = "wrapped " + (cause == null ? "nothing" : cause.getMessage());
        }
        check("exhausted attempts rethrow the LAST failure", "wrapped boom 2", outcome);
        check("stopped after maxAttempts calls", 2, failCalls[0]);

        int[] quickCalls = { 0 };
        Flaky instant = () -> {
            quickCalls[0]++;
            return "fast";
        };
        try {
            check("immediate success", "fast", Retrier.retry(instant, 4));
        } catch (Exception e) {
            check("immediate success", "fast", "threw " + e.getClass().getSimpleName());
        }
        check("success stops the retrying", 1, quickCalls[0]);
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

