interface Flaky {
    String attempt() throws Exception;
}

public class Retrier {

    public static String retry(Flaky task, int maxAttempts) {
        Exception last = null;
        for (int i = 0; i < maxAttempts; i++) {
            try {
                return task.attempt();
            } catch (Exception e) {
                last = e;
            }
        }
        throw new RuntimeException(last);
    }
}
